using System;
using System.IO;
using System.Text;
using System.Collections.Generic;
namespace SCUMLab {
public static class SelfTests {
    static List<string> passed=new List<string>();
    static void Expect(bool value,string message){if(!value)throw new Exception("Test failed: "+message);}
    static void Reject(Action action,string message){bool failed=false;try{action();}catch{failed=true;}Expect(failed,message);passed.Add(message);}
    static InstalledState Stage(string directory,string version,Dictionary<string,string> contents){Directory.CreateDirectory(directory);InstalledState s=new InstalledState{subfolder=true,version=version,steamBuildId="26621909"};foreach(var p in contents){string file=Path.Combine(directory,p.Key);File.WriteAllText(file,p.Value);s.files[p.Key]=Data.Hash(file);}return s;}
    sealed class BadSource:IReleaseSource { public Channel Channel(){return null;}public void Download(AssetSpec a,string tag,string destination){File.WriteAllText(destination,"wrong bytes");} }
    static Channel Manifest(){return new Channel{schemaVersion=1,version="0.1.0",tag="v0.1.0",minLauncherVersion="0.1.0",clientSteamBuildId="26621909",serverSteamBuildId="26621903",experimental=true,files=new[]{new AssetSpec{name="pakchunk950-SCUMLabTest_P.pak",bytes=3,sha256=new string('a',64)}},registryDelta=new AssetSpec{name="chair-registry-delta.json",bytes=3,sha256=new string('b',64)}};}
    static string FakeClient(string library,string name){string root=Path.Combine(library,"steamapps","common",name);Directory.CreateDirectory(Path.Combine(root,"SCUM","Content","Paks"));Directory.CreateDirectory(Path.Combine(root,"SCUM","Binaries","Win64"));File.WriteAllText(Path.Combine(root,"SCUM","Binaries","Win64","SCUM.exe"),"");Directory.CreateDirectory(Path.Combine(library,"steamapps"));File.WriteAllText(Path.Combine(library,"steamapps","appmanifest_513710.acf"),"\"installdir\" \""+name+"\"");return root;}
    static void DiscoveryTests(string root){
        string steam=Path.Combine(root,"Steam"),library=Path.Combine(root,"Другой диск","Игры Steam"),client=FakeClient(library,"My SCUM Client");Directory.CreateDirectory(Path.Combine(steam,"steamapps"));string vdf=Path.Combine(steam,"steamapps","libraryfolders.vdf");
        File.WriteAllText(vdf,"\"libraryfolders\" { \"1\" { \"path\" \""+library.Replace("\\","\\\\")+"\" } }");string[] found=GameDiscovery.FromLibraries(new[]{steam,steam});Expect(found.Length==1&&found[0]==client,"Custom library path/installdir");passed.Add("Discovery finds custom Steam library with spaces and Unicode");
        File.WriteAllText(vdf,"\"LibraryFolders\" { \"1\" \""+library.Replace("\\","\\\\")+"\" }");Expect(GameDiscovery.FromLibraries(new[]{steam}).Length==1,"Legacy libraryfolders");passed.Add("Discovery supports legacy Steam library format");
        string second=Path.Combine(root,"Second Library"),client2=FakeClient(second,"SCUM");found=GameDiscovery.FromLibraries(new[]{steam,second,second,Path.Combine(root,"missing")});Expect(found.Length==2&&Array.IndexOf(found,client2)>=0,"Multiple clients deduplication");passed.Add("Discovery returns all clients without duplicate paths");
        File.WriteAllText(Path.Combine(library,"steamapps","appmanifest_513710.acf"),"\"installdir\" \"..\\..\\outside\"");Expect(GameDiscovery.FromLibraries(new[]{library}).Length==0,"Unsafe installdir accepted");passed.Add("Discovery rejects manifest traversal and missing clients");
        string scanRoot=Path.Combine(root,"Unregistered"),portable=Path.Combine(scanRoot,"Games","Custom Location","My Client");Directory.CreateDirectory(Path.Combine(portable,"SCUM","Content","Paks"));Directory.CreateDirectory(Path.Combine(portable,"SCUM","Binaries","Win64"));File.WriteAllText(Path.Combine(portable,"SCUM","Binaries","Win64","SCUM.exe"),"");GameSearchResult scan=GameDiscovery.Scan(new[]{scanRoot},100,5,TimeSpan.FromSeconds(3));Expect(scan.paths.Length==1&&scan.paths[0]==portable,"Bounded disk discovery");passed.Add("Disk discovery finds client outside registered Steam libraries");
        scan=GameDiscovery.Scan(new[]{scanRoot},1,5,TimeSpan.FromSeconds(3));Expect(scan.limited&&scan.paths.Length==0,"Search budget ignored");passed.Add("Disk discovery reports bounded incomplete searches");
        File.Move(Path.Combine(portable,"SCUM","Binaries","Win64","SCUM.exe"),Path.Combine(portable,"SCUM","Binaries","Win64","SCUMServer.exe"));Expect(!GameDiscovery.IsClient(portable)&&GameDiscovery.Scan(new[]{scanRoot},100,5,TimeSpan.FromSeconds(3)).paths.Length==0,"Server discovered as client");passed.Add("Client discovery excludes dedicated server installations");
    }
    static void LegacyLayoutTests(string root){
        string gameRoot=Path.Combine(root,"g s");Directory.CreateDirectory(Path.Combine(gameRoot,"SCUM","Content","Paks"));Directory.CreateDirectory(Path.Combine(gameRoot,"SCUM","Binaries","Win64"));File.WriteAllText(Path.Combine(gameRoot,"SCUM","Binaries","Win64","SCUM.exe"),"");Directory.CreateDirectory(Path.Combine(gameRoot,"steamapps"));File.WriteAllText(Path.Combine(gameRoot,"steamapps","appmanifest_513710.acf"),"\n\"buildid\" \"26621909\"\n\"StateFlags\" \"4\"");
        GameInstall game=GameInstall.Open(gameRoot);UpdateService service=new UpdateService(game,new BadSource(),delegate{});service.StopCheck=delegate{};string name="pakchunk950-SCUMLabLegacy_P.pak",stage=Path.Combine(root,"legacy-stage");InstalledState legacy=Stage(stage,"0.1.4",new Dictionary<string,string>{{name,"legacy PAK"}});legacy.subfolder=false;File.WriteAllText(Path.Combine(game.Paks,"stock.pak"),"stock");service.Commit(stage,legacy,null);
        // Old journals and installed.json had no subfolder member at all.
        string tx=Directory.GetDirectories(service.Transactions)[0],journal=Path.Combine(tx,"journal.json");Data.AtomicText(journal,File.ReadAllText(journal).Replace("\"subfolder\":false,",""));Data.AtomicText(service.StatePath,File.ReadAllText(service.StatePath).Replace("\"subfolder\":false,",""));Expect(service.Verify(service.State()),"Legacy state without layout field");passed.Add("Legacy root installation remains verifiable");
        bool guidance=false;try{service.Sync(Manifest(),true);}catch(InvalidDataException ex){guidance=ex.Message.Contains("Откатить версию");}Expect(guidance&&File.Exists(Path.Combine(game.Paks,name)),"Legacy transition guidance and preservation");passed.Add("Legacy layout requires rollback before changing installation directory");
        service.Rollback();Expect(!File.Exists(Path.Combine(game.Paks,name))&&File.ReadAllText(Path.Combine(game.Paks,"stock.pak"))=="stock","Legacy rollback targets root only");passed.Add("Old journal rollback preserves stock files");
        InstalledState current=Stage(Path.Combine(root,"new-stage"),Data.Version,new Dictionary<string,string>{{name,"new nested PAK"}});service.Commit(Path.Combine(root,"new-stage"),current,null);Expect(File.Exists(Path.Combine(game.Paks,"SCUMLab",name))&&!File.Exists(Path.Combine(game.Paks,name))&&service.Verify(service.State()),"Nested install after rollback");passed.Add("New installation uses SCUMLab subfolder after legacy rollback");
        System.Diagnostics.ProcessStartInfo launch=GameLaunch.ClientInfo(game);Expect(launch.FileName==game.Exe&&launch.Arguments=="-fileopenlog"&&launch.WorkingDirectory==Path.GetDirectoryName(game.Exe)&&!launch.UseShellExecute,"Client launch mode");passed.Add("Mod client launch targets installed EXE with fileopenlog");game.Server=true;Reject(()=>GameLaunch.ClientInfo(game),"Client launcher rejects dedicated server installation");
    }
    static void ParkTests(string root){
        string gameRoot=Path.Combine(root,"p g");Directory.CreateDirectory(Path.Combine(gameRoot,"SCUM","Content","Paks"));Directory.CreateDirectory(Path.Combine(gameRoot,"SCUM","Binaries","Win64"));File.WriteAllText(Path.Combine(gameRoot,"SCUM","Binaries","Win64","SCUM.exe"),"");Directory.CreateDirectory(Path.Combine(gameRoot,"steamapps"));File.WriteAllText(Path.Combine(gameRoot,"steamapps","appmanifest_513710.acf"),"\n\"buildid\" \"26621909\"\n\"StateFlags\" \"4\"");
        GameInstall game=GameInstall.Open(gameRoot);UpdateService service=new UpdateService(game,new BadSource(),delegate{});service.StopCheck=delegate{};string name="pakchunk960-SCUMLabPark_P.pak",stage=Path.Combine(root,"park-stage"),managed=Path.Combine(game.Paks,"SCUMLab");
        InstalledState st=Stage(stage,"0.1.0",new Dictionary<string,string>{{name,"mod pak"},{Data.RegistryName,"registry pak"}});service.Commit(stage,st,null);File.WriteAllText(Path.Combine(game.Paks,"stock.pak"),"stock");File.WriteAllText(Path.Combine(managed,"foreign.pak"),"foreign");
        Reject(()=>service.Enable(),"Enable without parked mods refused");
        service.Disable();Expect(service.Parked&&!File.Exists(Path.Combine(managed,name))&&!File.Exists(Path.Combine(managed,Data.RegistryName))&&File.Exists(Path.Combine(service.ParkedDir,name))&&File.ReadAllText(Path.Combine(managed,"foreign.pak"))=="foreign"&&File.ReadAllText(Path.Combine(game.Paks,"stock.pak"))=="stock","Disable moves only own files");passed.Add("Mods disable parks only own PAKs outside Paks");
        Reject(()=>service.Rollback(),"Rollback refused while mods are parked");
        service.Enable();Expect(!service.Parked&&service.Verify(service.State())&&!File.Exists(Path.Combine(service.ParkedDir,name)),"Enable restores verified files");passed.Add("Mods enable restores verified PAKs");
        service.Disable();File.Move(Path.Combine(service.ParkedDir,name),Path.Combine(managed,name));service.Enable();Expect(!service.Parked&&service.Verify(service.State()),"Interrupted switch completes");passed.Add("Interrupted mods switch completes on enable");
        service.Disable();File.WriteAllText(Path.Combine(service.ParkedDir,Data.RegistryName),"damaged");Reject(()=>service.Enable(),"Damaged parked file refused");Expect(service.Parked&&File.Exists(Path.Combine(service.ParkedDir,name))&&!File.Exists(Path.Combine(managed,name)),"Refused enable changed files");passed.Add("Damaged parked file is not restored into the game");
    }
    static void MaintenanceTests(string root){
        string local=Path.Combine(root,"Local"),source=Path.Combine(local,"SCUM"),saved=Path.Combine(source,"Saved","SaveFiles");Directory.CreateDirectory(saved);File.WriteAllText(Path.Combine(saved,"singleplayer.db"),"precious save");File.WriteAllText(Path.Combine(source,"settings.ini"),"personal settings");string other=Path.Combine(local,"OtherGame");Directory.CreateDirectory(other);File.WriteAllText(Path.Combine(other,"keep.txt"),"untouched");ClientMaintenance maintenance=new ClientMaintenance(local);maintenance.ClientStopped=delegate{};
        maintenance.ClientStopped=delegate{throw new InvalidDataException("client running");};Reject(()=>maintenance.Clear(),"Client reset refuses running game before changing data");Expect(Directory.Exists(source)&&!Directory.Exists(maintenance.BackupRoot),"Running client reset changed files");maintenance.ClientStopped=delegate{};
        ClientResetResult result=maintenance.Clear();Expect(result.changed&&!Directory.Exists(source)&&File.ReadAllText(Path.Combine(result.backup,"Saved","SaveFiles","singleplayer.db"))=="precious save"&&File.ReadAllText(Path.Combine(result.backup,"settings.ini"))=="personal settings","Reset lost files");passed.Add("Client reset preserves saves and settings in complete backup");Expect(File.ReadAllText(Path.Combine(other,"keep.txt"))=="untouched","Other local app changed");passed.Add("Client reset touches only SCUM local application data");Expect(!maintenance.Clear().changed&&Directory.Exists(result.backup),"Repeat reset changed backup");passed.Add("Absent client data reset is a no-op");
        Directory.CreateDirectory(source);File.WriteAllText(Path.Combine(source,"new.ini"),"fresh session");ClientResetResult again=maintenance.Clear();Expect(again.backup!=result.backup&&File.ReadAllText(Path.Combine(again.backup,"new.ini"))=="fresh session"&&Directory.Exists(result.backup),"Backups overwritten");passed.Add("Repeated resets preserve separate backups");
        Directory.CreateDirectory(source);using(FileStream gate=new FileStream(Path.Combine(maintenance.BackupRoot,"maintenance.lock"),FileMode.Open,FileAccess.ReadWrite,FileShare.None)){Reject(()=>maintenance.Clear(),"Concurrent client maintenance is refused");}Expect(Directory.Exists(source),"Lock contention changed source");
        Directory.Move(result.backup,Path.Combine(root,"restored-saved-data"));Expect(File.ReadAllText(Path.Combine(root,"restored-saved-data","Saved","SaveFiles","singleplayer.db"))=="precious save","Backup cannot be restored");passed.Add("Client backup remains a directly restorable directory");
    }
    static string PakString(BinaryReader reader){int count=reader.ReadInt32();Expect(count>=0&&count<1024,"PAK string extent");return count==0?"":Encoding.ASCII.GetString(reader.ReadBytes(count-1))+((reader.ReadByte()==0)?"":throwPakString());}
    static string throwPakString(){throw new Exception("PAK string lacks terminator");}
    static void VerifyRegistryLookup(string file,byte[] payload){
        using(BinaryReader reader=new BinaryReader(File.OpenRead(file))){
            reader.BaseStream.Seek(-196,SeekOrigin.End);long primary=reader.ReadInt64();reader.BaseStream.Position=primary;string mount=PakString(reader);Expect(mount=="../../../SCUM/"&&reader.ReadInt32()==1,"Registry mount");reader.ReadUInt64();Expect(reader.ReadInt32()==0&&reader.ReadInt32()==1,"Registry directory index present");long directory=reader.ReadInt64();reader.BaseStream.Position=directory;int count=reader.ReadInt32();bool found=false;
            // FPakFile::SplitPathInline maps a root-level filename to directory '/'.
            for(int i=0;i<count;i++){string folder=PakString(reader);int files=reader.ReadInt32();for(int j=0;j<files;j++){string name=PakString(reader);int location=reader.ReadInt32();if(folder=="/"&&name=="AssetRegistry.bin"&&location==0)found=true;}}
            Expect(found,"Native directory lookup cannot resolve mounted AssetRegistry.bin");reader.BaseStream.Position=53;Expect(Convert.ToBase64String(reader.ReadBytes(payload.Length))==Convert.ToBase64String(payload),"Looked-up registry payload differs");
        }passed.Add("Registry PAK root filename resolves using Unreal lookup semantics");
    }
    static byte[] EmptyRegistry(){using(MemoryStream m=new MemoryStream())using(BinaryWriter w=new BinaryWriter(m)){w.Write(new byte[]{0xe7,0x9e,0x7f,0x71,0x3a,0x49,0xb0,0xe9,0x32,0x91,0xb3,0x88,0x07,0x81,0x38,0x1b});w.Write(8);w.Write(1);w.Write(4);w.Write(0UL);w.Write(0UL);w.Write((byte)0);w.Write((byte)4);w.Write(Encoding.ASCII.GetBytes("None"));w.Write(0x12345678);for(int i=0;i<11;i++)w.Write(0);w.Write(0x87654321U);w.Write(0);w.Write(4L);w.Write(0);w.Write(0);return m.ToArray();}}
    public static int Run(string root){
        Directory.CreateDirectory(root);Data.Require(Directory.GetFileSystemEntries(root).Length==0,"Test directory must be empty");try{
            DiscoveryTests(Path.Combine(root,"discovery"));
            LegacyLayoutTests(Path.Combine(root,"l"));
            MaintenanceTests(Path.Combine(root,"m"));
            ParkTests(Path.Combine(root,"p"));
            foreach(string missing in new string[]{null,"","   ","\"\""}){bool helpful=false;try{GameInstall.Open(missing);}catch(InvalidDataException ex){helpful=ex.Message.Contains("Выберите папку SCUM");}Expect(helpful,"Empty path must explain folder selection");}passed.Add("Missing game path gives actionable folder guidance");
            Reject(()=>GameInstall.NormalizeRoot("SCUM"),"Relative game path rejected");Reject(()=>GameInstall.NormalizeRoot("C:\\SCUM|invalid"),"Invalid game path rejected without framework error");Expect(GameInstall.NormalizeRoot(" \"C:\\Games With Spaces\\SCUM\" ")==Path.GetFullPath("C:\\Games With Spaces\\SCUM"),"Quoted paths with spaces");passed.Add("Quoted game paths with spaces normalized");
            Channel c=Manifest();Data.Validate(c);passed.Add("Valid release manifest accepted");c.files[0].name="../stock.pak";Reject(()=>Data.Validate(c),"Manifest path traversal rejected");c=Manifest();c.files[0].name=Data.RegistryName;Reject(()=>Data.Validate(c),"Remote registry replacement rejected");
            string gameRoot=Path.Combine(root,"game"),stockPaks=Path.Combine(gameRoot,"SCUM","Content","Paks"),paks=Path.Combine(stockPaks,"SCUMLab");Directory.CreateDirectory(paks);Directory.CreateDirectory(Path.Combine(gameRoot,"SCUM","Binaries","Win64"));File.WriteAllText(Path.Combine(gameRoot,"SCUM","Binaries","Win64","SCUM.exe"),"");Directory.CreateDirectory(Path.Combine(gameRoot,"steamapps"));File.WriteAllText(Path.Combine(gameRoot,"steamapps","appmanifest_513710.acf"),"\"buildid\" \"26621909\"");
            File.AppendAllText(Path.Combine(gameRoot,"steamapps","appmanifest_513710.acf"),"\n\"StateFlags\" \"4\"");File.WriteAllText(Path.Combine(stockPaks,"stock.pak"),"untouched");GameInstall game=GameInstall.Open(gameRoot);UpdateService service=new UpdateService(game,new BadSource(),delegate{});service.StopCheck=delegate{};
            c=Manifest();c.clientSteamBuildId="0";Reject(()=>service.Compatible(c),"Unsupported game build rejected");c=Manifest();Channel selected=c;Reject(()=>service.Sync(selected,false),"Experimental install requires opt-in");Reject(()=>service.Sync(selected,true),"Corrupt download rejected before installation");Expect(!File.Exists(service.StatePath),"Bad download created state");
            string firstName="pakchunk950-SCUMLabTest_P.pak",secondName="pakchunk951-SCUMLabExtra_P.pak";
            string firstStage=Path.Combine(root,"stage1");InstalledState first=Stage(firstStage,"0.1.0",new Dictionary<string,string>{{firstName,"version one"},{secondName,"old extra"}});service.Commit(firstStage,first,null);Expect(service.Verify(service.State()),"First install hashes");passed.Add("Initial install and state verification");
            string secondStage=Path.Combine(root,"stage2");InstalledState second=Stage(secondStage,"0.2.0",new Dictionary<string,string>{{firstName,"version two"}});service.AfterWrite=n=>{if(n==1)throw new IOException("simulated interrupted write");};Reject(()=>service.Commit(secondStage,second,first),"Mid-transaction failure rolls back");service.AfterWrite=null;Expect(service.Verify(first),"Recovery did not restore all old files");passed.Add("Old state and all old files restored after partial failure");
            string[] incomplete=Directory.GetDirectories(service.Transactions);Array.Sort(incomplete,StringComparer.Ordinal);string pendingTx=incomplete[incomplete.Length-1],pendingFile=Path.Combine(pendingTx,"journal.json");Journal pending=Data.Read<Journal>(pendingFile);pending.status="pending";Data.Write(pendingFile,pending);File.Copy(Path.Combine(secondStage,firstName),Path.Combine(paks,firstName),true);service.Recover();Expect(service.Verify(first),"Pending journal did not recover");passed.Add("Interrupted journal recovered on next operation");
            service.Commit(secondStage,second,first);Expect(!File.Exists(Path.Combine(paks,secondName))&&service.Verify(second),"Obsolete managed file removal");passed.Add("Obsolete owned files removed");
            service.Rollback();Expect(service.Verify(first),"Rollback to first install");passed.Add("Rollback restores previous version");
            File.WriteAllText(Path.Combine(paks,firstName),"manual edit");Reject(()=>service.Rollback(),"User-edited files preserved on rollback");File.Copy(Path.Combine(firstStage,firstName),Path.Combine(paks,firstName),true);service.Rollback();Expect(!File.Exists(Path.Combine(paks,firstName))&&!File.Exists(Path.Combine(paks,secondName)),"First install rollback removes only own files");Expect(File.ReadAllText(Path.Combine(stockPaks,"stock.pak"))=="untouched","Stock file changed");passed.Add("First-install rollback preserves unmanaged files");
            File.WriteAllText(Path.Combine(paks,firstName),"preexisting unknown file");Reject(()=>service.Commit(firstStage,first,null),"Unmanaged name collision rejected");Expect(File.ReadAllText(Path.Combine(paks,firstName))=="preexisting unknown file","Collision overwritten");
            RegistryDelta delta=new RegistryDelta{entries=new[]{new DeltaEntry{objectPath="/Game/SCUMLab/Test.Test",packageName="/Game/SCUMLab/Test",packagePath="/Game/SCUMLab",assetName="Test",assetClass="PlaceableCraftingRecipe",tags=new Dictionary<string,TagValue>{{"PrimaryAssetType",new TagValue{storageType="NumberlessName",value="PlaceableCraftingRecipe"}},{"NativeClass",new TagValue{storageType="AnsiString",value="Class'/Script/SCUM.PlaceableCraftingRecipe'"}}}}}};
            using(FileStream competing=new FileStream(Path.Combine(service.Work,"update.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None))Reject(()=>service.Sync(Manifest(),true),"Concurrent update rejected");
            byte[] baseline=EmptyRegistry(),merged=RegistryMerge.Merge(baseline,delta);File.WriteAllBytes(Path.Combine(root,"registry.bin"),merged);RegistryPak.Write(Path.Combine(root,"registry.pak"),merged);Reject(()=>RegistryMerge.Merge(merged,delta),"Duplicate registry entries rejected");delta.entries[0].objectPath="/Game/Foreign/Test.Test";Reject(()=>RegistryMerge.Merge(baseline,delta),"Foreign registry namespace rejected");passed.Add("Local registry generated and packed");
            List<DeltaEntry> many=new List<DeltaEntry>();for(int i=0;i<300;i++){string n="Bulk"+i;many.Add(new DeltaEntry{objectPath="/Game/SCUMLab/Bulk/"+n+"."+n,packageName="/Game/SCUMLab/Bulk/"+n,packagePath="/Game/SCUMLab/Bulk",assetName=n,assetClass="Blueprint",tags=new Dictionary<string,TagValue>{{"PrimaryAssetType",new TagValue{storageType="NumberlessName",value="BaseBuilding"}}}});}
            byte[] bulk=RegistryMerge.Merge(baseline,new RegistryDelta{entries=many.ToArray()});Expect(bulk.Length>baseline.Length,"Bulk registry merge");Reject(()=>RegistryMerge.Merge(bulk,new RegistryDelta{entries=many.ToArray()}),"Bulk duplicate rejected");passed.Add("Registry delta above 255 entries merged");
            VerifyRegistryLookup(Path.Combine(root,"registry.pak"),merged);
            Expect(SelfUpdater.IsNewer("v0.1.3","0.1.2")&&!SelfUpdater.IsNewer("v0.1.2","0.1.2")&&!SelfUpdater.IsNewer("v0.1.1","0.1.2"),"Self-update version comparison");passed.Add("Self-update blocks same-version and downgrade installs");
            string updaterRoot=Path.Combine(root,"self-update"),stagedRoot=Path.Combine(updaterRoot,"stage");Directory.CreateDirectory(stagedRoot);string stagedExe=Path.Combine(stagedRoot,"SCUMLabLauncher.exe"),targetExe=Path.Combine(updaterRoot,"SCUMLabLauncher.exe");File.Copy(System.Reflection.Assembly.GetExecutingAssembly().Location,stagedExe);File.WriteAllText(targetExe,"old launcher");string oldHash=LauncherUpdateTransaction.Hash(targetExe),newHash=LauncherUpdateTransaction.Hash(stagedExe);
            Func<LauncherUpdateJob> updateJob=()=>new LauncherUpdateJob{target=targetExe,staged=stagedExe,oldSHA256=oldHash,newSHA256=newHash,expectedVersion=Data.Version,token=Guid.NewGuid().ToString("N"),restart=false};
            LauncherUpdateJob damaged=updateJob();damaged.newSHA256=new string('0',64);Reject(()=>LauncherUpdateTransaction.Apply(damaged,null),"Damaged launcher update rejected");Expect(LauncherUpdateTransaction.Hash(targetExe)==oldHash,"Damaged update changed current EXE");
            LauncherUpdateJob wrongVersion=updateJob();wrongVersion.expectedVersion="99.0.0";Reject(()=>LauncherUpdateTransaction.Apply(wrongVersion,null),"Wrong launcher binary version rejected");
            string launcherBackup=LauncherUpdateTransaction.Apply(updateJob(),null);Expect(LauncherUpdateTransaction.Hash(targetExe)==newHash&&LauncherUpdateTransaction.Hash(launcherBackup)==oldHash,"Launcher atomic replacement");passed.Add("Launcher replacement preserves verified previous EXE");File.WriteAllText(targetExe,"old launcher");
            Reject(()=>LauncherUpdateTransaction.Apply(updateJob(),delegate{throw new IOException("simulated restart failure");}),"Launcher restart failure triggers rollback");Expect(LauncherUpdateTransaction.Hash(targetExe)==oldHash,"Launcher restart failure lost old EXE");
            using(Stream helper=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream("SCUMLab.Updater.exe"))Expect(helper!=null&&helper.Length>0,"Embedded update helper");passed.Add("Standalone update helper embedded in launcher");
            Data.Write(Path.Combine(root,"result.json"),new{ok=true,tests=passed.Count,checks=passed});return 0;
        }catch(Exception ex){Data.Write(Path.Combine(root,"result.json"),new{ok=false,checks=passed,error=ex.ToString()});return 1;}
    }
}
}
